    public static string Render(ProjectInfo info)
    {
        var key = HtmlEncoder.Default.Encode(info.Key);
        var mark = info.Key switch { "helpdesk" => "HD", "inventory" => "ST", "wallet" => "₤", "documents" => "DOC", "inspections" => "✓", "legacy" => ">_", "hr" => "HR", _ => "APP" };
        var examples = JsonSerializer.Serialize(Examples[info.Key], new JsonSerializerOptions(JsonSerializerDefaults.Web));
        var html = """
            <!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#20304a"><title>@@TITLE@@</title><style>@@STYLES@@</style></head>
            <body class="app-@@KEY@@"><header class="top"><div class="brand"><span class="mark">@@MARK@@</span><div><h1>@@TITLE@@</h1><p>@@PURPOSE@@</p></div></div><span class="local">ENTORNO LOCAL · DEMO</span></header>
            <main class="page"><form id="login" class="login"><div class="field"><label for="username">Perfil</label><select id="username" required></select></div><div class="field"><label for="password">Contraseña demo</label><input id="password" type="password" value="Demo123!" autocomplete="current-password" required></div><button class="btn" type="submit">Iniciar sesión</button><button class="soft" id="logout" type="button">Salir</button><div id="session" class="user-status">Inicia sesión para cargar tus datos.</div></form>
            <div id="workspace">@@WORKSPACE@@</div>
            <details class="api-tools"><summary>Consola de API y diagnóstico</summary><div class="tools"><section><p class="request-status">La contraseña es de demostración. No uses estas cuentas en producción.</p><div class="tool-fields"><div><label for="example">Operación</label><select id="example"></select></div><div><label for="method">Método HTTP</label><select id="method"><option>GET</option><option>POST</option><option>PUT</option><option>PATCH</option></select></div><div><label for="path">Ruta</label><input id="path"></div><div><label for="body">Cuerpo JSON</label><textarea id="body"></textarea></div><div class="tool-buttons"><button class="btn" id="send" type="button">Enviar operación</button><button class="soft" id="refresh" type="button">Actualizar tablero</button></div><div id="requestStatus" class="request-status"></div></div></section><section><h3>Respuesta</h3><pre class="response" id="output">Inicia sesión para consultar la API.</pre></section></div></details><p class="foot">ASP.NET Core · .NET 10 · datos sintéticos · uso local</p></main>
            <script>
            const appKey="@@KEY@@",examples=@@EXAMPLES@@,byId=id=>document.getElementById(id);let dataUser="";
            const esc=v=>String(v??"").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;").replace(/'/g,"&#39;");
            const tag=v=>'<span class="tag">'+esc(v||"—")+'</span>',empty=m=>'<div class="empty">'+esc(m)+'</div>';
            function set(id,v){const n=byId(id);if(n)n.textContent=v}
            function records(items,fn,msg){return items.length?items.map(fn).join(""):empty(msg)}
            function table(head,rows){return '<div class="table-wrap"><table><thead><tr>'+head.map(x=>'<th>'+esc(x)+'</th>').join("")+'</tr></thead><tbody>'+rows+'</tbody></table></div>'}
            function render(d){d=d||{};
              if(appKey==="helpdesk"){const a=d.tickets||[],open=a.filter(x=>!["Cerrado","Resuelto"].includes(x.status));set("metric-a",open.length);set("metric-b",a.filter(x=>["Alta","Urgente"].includes(x.priority)&&!["Cerrado","Resuelto"].includes(x.status)).length);set("metric-c",a.length-open.length);byId("primary-list").innerHTML=a.length?table(["Ticket","Asunto","Prioridad","Estado"],a.slice(0,12).map(x=>'<tr><td>#'+esc(x.number)+'</td><td>'+esc(x.title)+'</td><td>'+tag(x.priority)+'</td><td>'+tag(x.status)+'</td></tr>').join("")):empty("No hay tickets visibles.");byId("secondary-list").innerHTML=records((d.events||[]).slice(0,6),x=>'<div class="record"><div><strong>'+esc(x.kind)+'</strong><small>#'+esc(x.ticketId)+' · '+esc(x.actor)+'</small></div>'+tag(x.after)+'</div>',"Sin actividad reciente.")}
              else if(appKey==="inventory"){const a=d.balances||[],m=d.movements||[];set("metric-a",a.reduce((s,x)=>s+Number(x.quantity||0),0).toLocaleString("es-PE"));set("metric-b",a.filter(x=>Number(x.quantity)<=Number(x.minStock)).length);set("metric-c",(d.products||[]).length);byId("primary-list").innerHTML=a.length?table(["SKU","Producto","Stock","Mínimo"],a.map(x=>'<tr><td>'+esc(x.sku)+'</td><td>'+esc(x.name)+'</td><td><b>'+esc(x.quantity)+'</b></td><td>'+esc(x.minStock)+'</td></tr>').join("")):empty("No hay existencias.");byId("secondary-list").innerHTML=records(m.slice(0,6),x=>'<div class="record"><div><strong>'+esc(x.type)+'</strong><small>'+esc(x.reference)+'</small></div>'+tag((Number(x.delta)>0?"+":"")+x.delta)+'</div>',"Sin movimientos.")}
              else if(appKey==="wallet"){const a=d.accounts||[],t=d.transfers||[];set("metric-a","PEN-DEMO "+a.reduce((s,x)=>s+Number(x.balance||0),0).toLocaleString("es-PE",{minimumFractionDigits:2,maximumFractionDigits:2}));byId("primary-list").innerHTML=records(a,x=>'<div class="record"><div><strong>'+esc(x.code)+'</strong><small>'+esc(x.owner)+' · '+esc(x.currency)+'</small></div><b>'+Number(x.balance||0).toFixed(2)+'</b></div>',"No hay cuentas visibles.");byId("secondary-list").innerHTML=records(t.slice(0,7),x=>'<div class="record"><div><strong>Transferencia demo</strong><small>'+esc(x.sourceAccountId)+' → '+esc(x.destinationAccountId)+'</small></div>'+tag("−"+Number(x.amount||0).toFixed(2))+'</div>',"No hay transferencias.")}
              else if(appKey==="documents"){const a=d.documents||[],p=d.approvals||[];set("metric-a",a.length);set("metric-b",p.filter(x=>x.state==="Pendiente").length);set("metric-c",a.filter(x=>x.state==="Aprobada").length);byId("primary-list").innerHTML=records(a.slice(0,10),x=>'<div class="record"><div><strong>'+esc(x.title)+'</strong><small>'+esc(x.category)+' · '+esc(x.confidentiality)+'</small></div>'+tag(x.state)+'</div>',"No hay documentos visibles.");byId("secondary-list").innerHTML=records(p.slice(0,8),x=>'<div class="record"><div><strong>Documento #'+esc(x.documentId)+'</strong><small>Solicitante: '+esc(x.requester)+'</small></div>'+tag(x.state)+'</div>',"La bandeja está al día.")}
              else if(appKey==="inspections"){const a=d.inspections||[],f=d.findings||[];set("metric-a",a.length);set("metric-b",a.filter(x=>x.state!=="Cerrada").length);set("metric-c",f.filter(x=>x.state!=="Cerrado").length);byId("primary-list").innerHTML=records(a.slice(0,10),x=>'<div class="record"><div><strong>Recorrido #'+esc(x.id)+' · sede '+esc(x.siteId)+'</strong><small>'+esc(x.inspector)+' · puntaje '+esc(x.score)+'%</small></div>'+tag(x.state)+'</div>',"No hay recorridos.");byId("secondary-list").innerHTML=records(f.slice(0,8),x=>'<div class="record"><div><strong>'+esc(x.description)+'</strong><small>'+esc(x.severity)+' · #'+esc(x.inspectionId)+'</small></div>'+tag(x.state)+'</div>',"Sin hallazgos abiertos.")}
              else if(appKey==="legacy"){const a=d.requests||[],c=d.changes||[];set("metric-a",a.length);byId("primary-list").innerHTML=a.length?table(["Referencia","Solicitud","Estado","Prioridad"],a.slice(0,12).map(x=>'<tr><td>'+esc(x.number)+'</td><td>'+esc(x.title)+'</td><td>'+tag(x.state)+'</td><td>'+esc(x.priority)+'</td></tr>').join("")):empty("Baseline vacío.");byId("secondary-list").innerHTML=records(c.slice(0,7),x=>'<div class="record"><div><strong>'+esc(x.module)+'</strong><small>'+esc(x.change)+'</small></div>'+tag(x.risk)+'</div>',"Sin decisiones registradas.")}
              else if(appKey==="hr"){const a=d.attendance||[],p=d.leaveRequests||[];set("employee-name",dataUser.split(" · ")[0]||"equipo");set("metric-a",a.length?"Jornada registrada":"Sin marcación");set("metric-b",(d.employees||[]).length);set("metric-c",a.length);set("metric-d",p.filter(x=>x.state==="Pendiente").length);byId("primary-list").innerHTML=records(a.slice(0,8),x=>'<div class="record"><div><strong>'+esc(x.type)+'</strong><small>'+esc(x.date)+' · '+esc(x.time)+'</small></div>'+tag("Empleado #"+x.employeeId)+'</div>',"Aún no hay marcaciones.");byId("secondary-list").innerHTML=records(p.slice(0,8),x=>'<div class="record"><div><strong>'+esc(x.type)+'</strong><small>'+esc(x.from)+' a '+esc(x.to)+' · '+esc(x.reason)+'</small></div>'+tag(x.state)+'</div>',"Sin solicitudes de ausencia.")}
            }
            async function parsed(r){const t=await r.text();try{return JSON.parse(t)}catch{return t}}
            async function refresh(){const r=await fetch("/api/dashboard"),d=await parsed(r);if(r.ok){render(d);byId("output").textContent=JSON.stringify(d,null,2);byId("session").textContent="Sesión: "+dataUser;}else{render({});byId("output").textContent=JSON.stringify(d,null,2)}}
            async function setup(){const r=await fetch("/api/auth/demo-users"),u=await parsed(r);byId("username").innerHTML=u.map(x=>'<option value="'+esc(x.username)+'">'+esc(x.label)+' ('+esc(x.username)+') · '+esc(x.role)+'</option>').join("");byId("example").innerHTML=examples.map((x,i)=>'<option value="'+i+'">'+esc(x.label)+'</option>').join("");apply();const me=await fetch("/api/auth/me");if(me.ok){const x=await parsed(me);dataUser=x.username+" · "+x.role;await refresh()}else render({})}
            function apply(){const x=examples[Number(byId("example").value)||0];if(x){byId("method").value=x.method;byId("path").value=x.path;byId("body").value=x.body||""}}
            byId("login").addEventListener("submit",async e=>{e.preventDefault();const r=await fetch("/api/auth/login",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({username:byId("username").value,password:byId("password").value})});const d=await parsed(r);if(r.ok){dataUser=d.username+" · "+d.role;await refresh()}else{byId("session").textContent="Perfil o contraseña incorrectos.";byId("session").className="user-status error"}});
            byId("logout").addEventListener("click",async()=>{await fetch("/api/auth/logout",{method:"POST"});dataUser="";byId("session").textContent="Sesión cerrada.";render({})});
            byId("example").addEventListener("change",apply);byId("refresh").addEventListener("click",refresh);document.querySelectorAll("[data-refresh]").forEach(x=>x.addEventListener("click",refresh));
            document.querySelectorAll("[data-operation]").forEach(b=>b.addEventListener("click",()=>{const n=examples.findIndex(x=>x.label===b.getAttribute("data-operation"));if(n>=0){byId("example").value=String(n);apply();document.querySelector(".api-tools").open=true;document.querySelector(".api-tools").scrollIntoView({behavior:"smooth"})}}));
            byId("send").addEventListener("click",async()=>{const method=byId("method").value,headers={};let body;if(["POST","PUT","PATCH"].includes(method)&&byId("body").value.trim()){headers["Content-Type"]="application/json";body=byId("body").value}const b=byId("send");b.disabled=true;try{const r=await fetch(byId("path").value,{method,headers,body}),d=await parsed(r);byId("output").textContent=JSON.stringify({status:r.status,response:d},null,2);byId("requestStatus").textContent="HTTP "+r.status;if(r.ok)await refresh()}catch(e){byId("requestStatus").textContent=e.message}finally{b.disabled=false}});
            setup().catch(()=>{byId("session").textContent="No se pudo conectar con la aplicación."});
            </script></body></html>
            """;
        return html.Replace("@@TITLE@@", HtmlEncoder.Default.Encode(info.Title), StringComparison.Ordinal)
            .Replace("@@PURPOSE@@", HtmlEncoder.Default.Encode(info.Purpose), StringComparison.Ordinal)
            .Replace("@@KEY@@", key, StringComparison.Ordinal)
            .Replace("@@MARK@@", HtmlEncoder.Default.Encode(mark), StringComparison.Ordinal)
            .Replace("@@STYLES@@", Styles, StringComparison.Ordinal)
            .Replace("@@WORKSPACE@@", Workspaces[info.Key], StringComparison.Ordinal)
            .Replace("@@EXAMPLES@@", examples, StringComparison.Ordinal);
    }
}
